import java.util.Scanner;

public class Main {
    static final int MAXN = 250010;
    static long[] factorial = new long[MAXN];
    static long[] invFactorial = new long[MAXN];
    static long[][] dpTable = new long[30][MAXN];
    static int[] bitsArray = new int[MAXN];

    static long totalN, maxM, modM;

    static long nCr(int a, int b) {
        return factorial[a] * invFactorial[a - b] % modM * invFactorial[b] % modM;
    }

    static void addMod(LongWrapper x, long y) {
        x.value += y;
        if (x.value >= modM) x.value -= modM;
    }

    static class LongWrapper {
        long value;

        LongWrapper(long v) {
            this.value = v;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        totalN = sc.nextLong();
        maxM = sc.nextLong();
        modM = sc.nextLong();

        factorial[0] = 1;
        invFactorial[0] = 1;
        factorial[1] = 1;
        invFactorial[1] = 1;

        for (int i = 2; i <= totalN; i++) {
            long q = modM / i;
            long r = modM - i * q;
            factorial[i] = factorial[i - 1] * i % modM;
            invFactorial[i] = modM - (q * invFactorial[(int) r] % modM);
        }

        for (int i = 2; i <= totalN; i++) {
            invFactorial[i] = invFactorial[i - 1] * invFactorial[i] % modM;
        }

        long answer = 1;
        for (int i = 1; i <= totalN; i++) {
            answer = answer * maxM % modM;
        }

        for (int i = 1; i <= totalN; i++) {
            bitsArray[i] = bitsArray[i >> 1] + (i & 1);
        }

        if (totalN % 2 == 1) {
            System.out.println(answer);
            return;
        }

        dpTable[0][0] = 1;
        int maxBitsCount = (int) Math.min(bitsArray[(int) totalN], maxM);

        for (int i = 0; i < maxBitsCount; i++) {
            for (int j = 0; j < totalN; j++) {
                if (dpTable[i][j] == 0) continue;
                int mask = (int) (totalN ^ j);
                for (int k = mask; k > j; k = (k - 1) & mask) {
                    int r = k | j;
                    LongWrapper temp = new LongWrapper(0);
                    addMod(temp, dpTable[i][j] * invFactorial[k] % modM);
                    dpTable[i + 1][r] = (dpTable[i + 1][r] + temp.value) % modM;
                }
            }
        }

        for (int i = 1; i <= maxM; i++) {
            long tempVal = dpTable[i][(int) totalN] * factorial[(int) maxM] % modM
                    * invFactorial[(int) (maxM - i)] % modM * factorial[(int) totalN] % modM;
            answer -= tempVal;
        }

        answer = (modM + answer % modM) % modM;
        System.out.println(answer);
        sc.close();
    }
}

